"""Самодостаточная страница PID тренажёра."""

PID_TRAINER_PAGE = r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PID тренажёр — bfemu</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0d1117;color:#e6edf3;font:15px/1.5 system-ui,sans-serif}
main{max-width:1320px;margin:auto;padding:28px}h1{font-size:30px;letter-spacing:-.03em;margin:0}h2{font-size:17px;margin:0 0 14px}
p{color:#a8b3c2;margin:8px 0}.eyebrow{color:#65d6b3;text-transform:uppercase;letter-spacing:.14em;font-size:12px;font-weight:700}
.subtitle{max-width:800px}.warning{background:#302414;border:1px solid #76582d;border-radius:10px;padding:12px 16px;margin:20px 0;color:#f3d19e}
.layout{display:grid;grid-template-columns:330px 1fr;gap:18px}.card{background:#161b22;border:1px solid #30363d;border-radius:14px;padding:20px;margin-bottom:18px}
label{display:block;color:#adb8c7;font-size:13px;margin-bottom:5px}select,input,button{font:inherit;color:#e6edf3;background:#0d1117;border:1px solid #465362;border-radius:8px;padding:9px}select{width:100%}button{cursor:pointer;font-weight:600}button:hover{border-color:#65d6b3}button.primary{background:#21856f;border-color:#21856f;color:white}button:disabled{opacity:.45;cursor:not-allowed}
.field{margin-bottom:16px}.gain{display:grid;grid-template-columns:30px 1fr 64px;gap:8px;align-items:center;margin:12px 0}.gain b{color:#65d6b3}.gain input[type=range]{width:100%;padding:0;accent-color:#65d6b3}.gain input[type=number]{width:100%;padding:6px}.actions{display:flex;gap:8px;flex-wrap:wrap}
.small{font-size:12px;color:#a8b3c2}.status{min-height:2em;margin-top:10px;color:#9bdcc8}.status.error{color:#ffb4a9}.chart{width:100%;height:280px;display:block;background:#0d1117;border:1px solid #30363d;border-radius:8px}.chart.terms{height:170px}.legend{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;margin:8px 0 14px;color:#a8b3c2}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.metric{background:#0d1117;padding:12px;border-radius:8px}.metric strong{display:block;font-size:20px;color:#e6edf3}.metric span{font-size:12px;color:#a8b3c2}details{border-top:1px solid #30363d;padding:10px 0}summary{cursor:pointer;font-weight:600}li{margin:6px 0;color:#a8b3c2}code{color:#8de3c4}@media(max-width:800px){main{padding:18px}.layout{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}.chart{height:240px}}
__NAV_STYLE__
</style></head><body>__NAV__<main>
<div class="eyebrow">Интерактивная лаборатория · Betaflight 4.5</div><h1>Почувствуйте PID</h1>
<p class="subtitle">Меняйте параметры активного профиля здесь или в Betaflight Configurator и наблюдайте реакцию учебной модели одной оси.</p>
<div class="warning"><b>Учебная модель, не полётный симулятор.</b> Это не PID-код Betaflight: фильтры, Feedforward, реальные рейты, моторы и взаимодействие осей не моделируются. Не переносите результаты на реальный дрон без проверки.</div>
<div class="layout"><div><section class="card"><h2>Настройки эксперимента</h2>
<div class="field"><label for="axis">Ось</label><select id="axis"><option value="roll">Roll · крен</option><option value="pitch">Pitch · тангаж</option><option value="yaw">Yaw · рыскание</option></select></div>
<div class="field"><label for="scenario">Сценарий</label><select id="scenario"><option value="step">Ступень · реакция на стик</option><option value="disturbance">Возмущение · порыв ветра</option><option value="reverse">Реверс · смена направления</option></select></div>
<p class="small" id="profile">Загрузка профиля…</p>
<div class="gain"><b>P</b><input type="range" id="p-range" min="0" max="250" aria-label="P ползунок"><input type="number" id="p" min="0" max="250" step="1" aria-label="P значение"></div>
<div class="gain"><b>I</b><input type="range" id="i-range" min="0" max="250" aria-label="I ползунок"><input type="number" id="i" min="0" max="250" step="1" aria-label="I значение"></div>
<div class="gain"><b>D</b><input type="range" id="d-range" min="0" max="250" aria-label="D ползунок"><input type="number" id="d" min="0" max="250" step="1" aria-label="D значение"></div>
<div class="actions"><button class="primary" id="apply" disabled>Применить к FC</button><button id="reload">Отменить изменения</button></div>
<div id="status" class="status" role="status" aria-live="polite"></div><p class="small">Применение меняет активный профиль в памяти. Для сохранения после перезапуска используйте Save в Configurator или <code>save</code> в CLI. В Configurator заново откройте вкладку PID для чтения изменений.</p></section>
<section class="card"><h2>Как подключить Configurator</h2><p>Запустите эмулятор с MSP и HTTP. В настольном Configurator выберите ручное TCP-подключение к адресу эмулятора, откройте PID Tuning и сохраните изменения. Страница заметит новый профиль и значения автоматически.</p><p class="small">Настольный Configurator подключается по TCP; браузерная PWA не поддерживает прямой TCP. Адрес и порт выводятся в консоль эмулятора.</p></section></div>
<div><section class="card"><div class="actions" style="justify-content:space-between;align-items:center"><div><div class="eyebrow">Замкнутый контур</div><h2>Отклик угловой скорости</h2></div><div class="actions"><button id="compare">Запомнить кривую</button><button id="clear">Убрать сравнение</button></div></div>
<canvas class="chart" id="graph" aria-label="График заданной и фактической угловой скорости"></canvas><div class="legend"><span><i class="dot" style="background:#8b949e"></i>Задание, °/с</span><span><i class="dot" style="background:#65d6b3"></i>Гироскоп, °/с</span><span><i class="dot" style="background:#e3b45b"></i>Сохранённая реакция</span></div>
<div class="metrics"><div class="metric"><strong id="overshoot">—</strong><span>Перерегулирование</span></div><div class="metric"><strong id="settling">—</strong><span>Установление в ±5%</span></div><div class="metric"><strong id="error">—</strong><span>Ошибка в конце окна, °/с</span></div></div>
<p class="small">Метрики рассчитаны для первой ступени: с 0,4 с до следующего события (или до 3 с). «Не установилось» означает, что до конца окна сигнал не удержался в полосе ±10 °/с.</p>
<h2>Вклад составляющих</h2><canvas class="chart terms" id="terms" aria-label="График составляющих P I D и управляющего сигнала"></canvas><div class="legend"><span style="color:#65d6b3">P</span><span style="color:#e3b45b">I</span><span style="color:#ae9dfc">D</span><span style="color:#e6edf3">Управление (ограничено ±1)</span></div><p class="small">Составляющие в условных единицах модели, не значения Blackbox.</p></section>
<section class="card"><h2>Практика</h2><details open><summary>1. Пропорциональная реакция</summary><p>Выберите «Ступень», уменьшите P и нажмите «Применить к FC». Сравните с исходной кривой. Увеличивайте P: следите за скоростью отклика и колебаниями. Остальные коэффициенты оставьте неизменными.</p></details><details><summary>2. Демпфирование D</summary><p>При выраженном перерегулировании сравните меньший и больший D. В этой модели D реагирует на скорость изменения гироскопа; в реальности чрезмерный D может усиливать шум и нагревать моторы, чего эта модель не показывает.</p></details><details><summary>3. Интеграл и возмущение</summary><p>Выберите «Возмущение». Сравните I = 0 и повышенный I: обратите внимание на устойчивую ошибку и восстановление после порыва. Проверяйте также перерегулирование.</p></details></section></div></div>
</main><script>
const $=id=>document.getElementById(id), terms=['p','i','d']; let baseline=null, dirty=false, conflict=false, latest=null, saved=null, busy=false;
function setStatus(text,error=false){$('status').textContent=text;$('status').className='status'+(error?' error':'')}
function values(){return Object.fromEntries(terms.map(k=>[k,Number($(k).value)]))}
function populate(v){for(const k of terms){$(k).value=v[k];$(k+'-range').value=v[k]}}
function same(a,b){return a&&b&&a.profile===b.profile&&a.axis===b.axis&&terms.every(k=>a.values[k]===b.values[k])}
function changed(){dirty=true; $('apply').disabled=false; setStatus('Изменения ещё не применены. График показывает активные значения FC.');}
for(const k of terms){$(k).addEventListener('input',()=>{let v=$(k).value;if(v!==''&&Number(v)>=0&&Number(v)<=250)$(k+'-range').value=v;changed()});$(k+'-range').addEventListener('input',()=>{$(k).value=$(k+'-range').value;changed()})}
async function refresh(force=false){if(busy)return;busy=true;try{const axis=$('axis').value,scenario=$('scenario').value;let r=await fetch('/api/pid-trainer?axis='+axis+'&scenario='+scenario,{cache:'no-store'});let data=await r.json();if(!r.ok)throw Error(data.error);if(axis!==$('axis').value||scenario!==$('scenario').value)return;
latest=data; $('profile').textContent='Активный профиль: '+data.profile+' · ось '+data.axis.toUpperCase();
if(force||!dirty){baseline={profile:data.profile,axis:data.axis,values:data.values};populate(data.values);dirty=false;conflict=false;$('apply').disabled=true;setStatus('Синхронизировано с FC.');}
else if(!same(baseline,data)){conflict=true;$('apply').disabled=true;setStatus('Профиль или значения изменились в Configurator. Отмените изменения и загрузите актуальные значения.',true)}
drawAll();}catch(e){setStatus('Нет связи с эмулятором: '+e.message,true)}finally{busy=false}}
$('apply').onclick=async()=>{if(!baseline||conflict)return;let v=values();if(terms.some(k=>$(k).value===''||!Number.isInteger(v[k])||v[k]<0||v[k]>250)){setStatus('Введите целые значения от 0 до 250.',true);return}try{let r=await fetch('/api/pid-trainer',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({axis:baseline.axis,profile:baseline.profile,expected:baseline.values,values:v})});let data=await r.json();if(!r.ok)throw Error(data.error);dirty=false;await refresh(true);setStatus('Применено к активному профилю в памяти FC.');}catch(e){setStatus(e.message,true);await refresh()}};
$('reload').onclick=()=>refresh(true);$('axis').onchange=()=>{dirty=false;baseline=null;saved=null;refresh(true)};$('scenario').onchange=()=>{saved=null;refresh()};
$('compare').onclick=()=>{if(latest){saved=latest.points.map(p=>p.slice());drawAll()}};$('clear').onclick=()=>{saved=null;drawAll()};
function chart(canvas,points,lines,ymin,ymax){let rect=canvas.getBoundingClientRect(),scale=window.devicePixelRatio||1;canvas.width=rect.width*scale;canvas.height=rect.height*scale;let c=canvas.getContext('2d');c.scale(scale,scale);let w=rect.width,h=rect.height,L=46,R=12,T=12,B=25,X=t=>L+t/3*(w-L-R),Y=v=>T+(ymax-v)/(ymax-ymin)*(h-T-B);c.font='11px system-ui';c.strokeStyle='#27313d';c.fillStyle='#8b949e';c.lineWidth=1;for(let j=0;j<=4;j++){let val=ymin+(ymax-ymin)*j/4,y=Y(val);c.beginPath();c.moveTo(L,y);c.lineTo(w-R,y);c.stroke();c.fillText(val.toFixed(ymax<=3?1:0),2,y+4)}for(let t=0;t<=3;t++){c.fillText(t+'s',X(t)-4,h-6)}for(const line of lines){if(!line.rows)continue;c.strokeStyle=line.color;c.lineWidth=line.width||2;c.setLineDash(line.dash||[]);c.beginPath();line.rows.forEach((p,i)=>{let x=X(p[0]),y=Y(p[line.col]);if(i===0)c.moveTo(x,y);else c.lineTo(x,y)});c.stroke()}c.setLineDash([])}
function drawAll(){if(!latest)return;let p=latest.points, max=Math.max(220,...p.map(x=>Math.abs(x[2])),...(saved||[]).map(x=>Math.abs(x[2])))*1.12;chart($('graph'),p,[{rows:p,col:1,color:'#8b949e',dash:[5,5]},{rows:saved,col:2,color:'#e3b45b',dash:[4,4]},{rows:p,col:2,color:'#65d6b3'}],-max,max);let m=Math.max(1,...p.flatMap(x=>x.slice(3).map(Math.abs)))*1.1;chart($('terms'),p,[{rows:p,col:3,color:'#65d6b3'},{rows:p,col:4,color:'#e3b45b'},{rows:p,col:5,color:'#ae9dfc'},{rows:p,col:6,color:'#e6edf3',width:1}],-m,m);let met=latest.metrics;$('overshoot').textContent=met.overshoot_pct+'%';$('settling').textContent=met.settling_s===null?'Не установилось':met.settling_s+' с';$('error').textContent=met.end_error}
window.addEventListener('resize',drawAll);refresh(true);setInterval(()=>refresh(),1200);
</script></body></html>'''
